mapper.sql:
/* tbsy_file_info[[SY][시스템] 첨부파일정보] SELECT */ SELECT tb1.seq /* 일련번호 BIGINT */ , tb1.mb_id /* 회사코드 VARCHAR(20) */ , tb1.file_no /* 파일번호 VARCHAR(40) */ , tb1.attach_gbn /* 첨부구분 VARCHAR(10) */ , tb2.cd_vl_nm AS attach_gbn_nm , tb1.board_no /* 게시판구분 게시판번호 VARCHAR(20) */ , tb1.ref_seq /* 첨부구분 해당테이블의 인덱스 VARCHAR(20) */ , tb1.doc_gbn /* 문서구분 VARCHAR(10) */ , tb1.file_path /* 파일경로(절대경로) VARCHAR(300) */ , tb1.file_url /* 파일URL(상대경로) VARCHAR(300) */ , tb1.file_nm /* 원파일명 VARCHAR(300) */ , tb1.file_size /* 파일크기 BIGINT */ , tb1.file_mime /* MIME타입 VARCHAR(100) */ , tb1.file_format /* 확장자 VARCHAR(5) */ , tb1.memo /* 메모 VARCHAR(100) */ , tb1.in_emp_cd /* 입력자사번 VARCHAR(20) */ , DATE_FORMAT(tb1.in_dtm, '%Y-%m-%d') AS in_dtm /* 입력일시 DATETIME */ , tb1.up_emp_cd /* 수정자사번 VARCHAR(20) */ , DATE_FORMAT(tb1.up_dtm, '%Y-%m-%d') AS up_dtm /* 수정일시 DATETIME */ FROM (SELECT * FROM tbsy_file_info WHERE mb_id = #{mb_id}
AND file_no = #{file_no}
AND seq = #{seq}
AND attach_gbn = #{attach_gbn}
AND ref_seq = #{ref_seq}
AND board_no = #{board_no}
AND file_mime LIKE CONCAT('%',#{file_mime},'%')
) tb1 LEFT OUTER JOIN (SELECT * FROM tbcm_common_code WHERE mb_id = #{mb_id} AND grp_cmm_cd = 'ATTACH_GBN' ) tb2 ON tb1.attach_gbn = tb2.cd_vl

mapper.select:
/* file-mapper.xml selectFileInfoCount 첨부파일정보 중복 확인(개수조회) */
SELECT COUNT(file_no) FROM tbsy_file_info 
 WHERE file_no   = #{file_no}
   AND mb_id     = #{mb_id}

mapper.delete:
/* file-mapper.xml deleteFileInfo 첨부파일정보(file_no) 삭제 */
DELETE
  FROM tbsy_file_info
 WHERE mb_id = #{mb_id}
   AND file_no = #{file_no}

/* file-mapper.xml "deleteFileInfoByRefIdx" 첨부파일정보(ref_seq) 삭제 */
DELETE
  FROM tbsy_file_info
 WHERE mb_id = #{mb_id}
   AND attach_gbn = #{attach_gbn}
   AND ref_seq = #{ref_seq}

mapper.update:
		/* file-mapper.xml updateBoardFileInfo 게시물이동시 파일 수정 */
		UPDATE tbsy_file_info /* [SY][시스템] 첨부파일정보 */
		   SET up_emp_cd   = #{up_emp_cd}      /* 수정자사번                   VARCHAR(20)  */
		     , up_dtm      = NOW()         /* 수정일시                     DATETIME     */
    		 , board_no    = #{board_no}       /* 게시판구분 게시판번호          VARCHAR(20)  */
		 WHERE mb_id = #{mb_id}
	    	AND attach_gbn = #{attach_gbn}
	    	AND ref_seq = #{ref_seq}

mapper.select:
/* file-mapper.xml id="selectTempFileInfoList" 임시파일정보 조회 */
SELECT file_path
  FROM tbsy_file_info
 WHERE mb_id = #{mb_id}
   AND attach_gbn = #{attach_gbn}
   AND memo = #{memo}

mapper.delete:
/* file-mapper.xml deleteTempFileInfo 임시파일정보 삭제 */
DELETE
  FROM tbsy_file_info
 WHERE mb_id = #{mb_id}
   AND attach_gbn = #{attach_gbn}
   AND memo = #{memo}

mapper.update:
/* file-mapper.xml updateTempFileInfo 임시파일정보 수정 */
UPDATE tbsy_file_info
   SET memo = ''
     , ref_seq = #{ref_seq}
 WHERE mb_id = #{mb_id}
   AND attach_gbn = #{attach_gbn}
   AND memo = #{memo}
